-- US content 1.3 «hot» (founder, 28/11/2026): two US Plus themes a little
-- spicier than the rest, for adult couples. No new game, no new function.
--
-- 1. 42 new Game V2 prompts (Quanto mi conosci?, Ridete, Scopritevi,
--    Confrontatevi, Rivivete) and 8 new Questo o quello cards, Italian and
--    English, on two themes: piccante (flirt, attraction, kisses, seduction,
--    daring dates) and desideri (closeness, romantic fantasies, cuddles,
--    surprises in bed said with elegance). The theme opens the topic
--    («piccante_prima_mossa»), so get_plus_preview_v1 groups them by theme.
--    The drafts in supabase/game-v2/content-1-3 are the human-reviewable
--    source; this migration carries the SQL generated from them between the
--    content-1-3 begin/end markers (node scripts/build-content-1-3-sql.mjs),
--    and tests/content-1-3-catalog.test.js fails when the two drift apart.
-- 2. Every new row is plus: the rule of content 1.2 (private.couple_has_plus,
--    read in private.game_v2_candidates, public.start_swipe_round and
--    public.play_us_answer) keeps them away from couples without Plus.
-- Only inserts; nothing existing changes or is deleted. Re-applying this
-- migration changes nothing.

-- Preflight: the plus columns of content 1.2 must be there.
do $content_1_3_preflight$
begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'game_v2_catalog' and column_name = 'plus')
     or not exists (select 1 from information_schema.columns where table_schema = 'private' and table_name = 'game_swipe_v1_catalog' and column_name = 'plus') then
    raise exception using errcode = 'P0001', message = 'content 1.3: run 20261128104908_contenuti_1_2 first';
  end if;
end;
$content_1_3_preflight$;

-- content-1-3:begin (generated by scripts/build-content-1-3-sql.mjs from supabase/game-v2/content-1-3; do not edit by hand)

-- Game V2 catalog: 42 new prompts (42 plus), Italian and English.
on conflict (id) do nothing;

-- Questo o quello: 8 new cards (8 plus), Italian and English.
on conflict (id) do nothing;

-- content-1-3:end

-- Postcondition: every piccante/desideri row is plus, active, with English.
do $content_1_3_check$
begin
  if exists (select 1 from public.game_v2_catalog
              where pg_catalog.split_part(topic, '_', 1) in ('piccante', 'desideri')
                and (not plus or not active or question_text_en is null
                  or (predict_text is not null and predict_text_en is null) or options_en is null)) then
    raise exception using errcode = 'P0001', message = 'content 1.3: a piccante/desideri prompt is not plus or has no English';
  end if;
  if exists (select 1 from private.game_swipe_v1_catalog
              where pg_catalog.split_part(topic, '_', 1) in ('piccante', 'desideri')
                and (not plus or not active or question_text_en is null or options_en is null)) then
    raise exception using errcode = 'P0001', message = 'content 1.3: a piccante/desideri card is not plus or has no English';
  end if;
end;
$content_1_3_check$;
